class Component extends DCLogic {
  constructor(props) {
    super(props);
    this.state = { dom: 'all', lvl: 'all', q: '' };
  }

  fa(str) {
    var map = { '0': '۰', '1': '۱', '2': '۲', '3': '۳', '4': '۴', '5': '۵', '6': '۶', '7': '۷', '8': '۸', '9': '۹' };
    return String(str).replace(/[0-9]/g, function (d) { return map[d]; });
  }

  filtered() {
    var s = this.state;
    var q = s.q.trim().toLowerCase();
    return IDEAS.filter(function (i) {
      if (s.dom !== 'all' && i.dom !== s.dom) { return false; }
      if (s.lvl !== 'all' && i.lvl !== s.lvl) { return false; }
      if (q && i.hay.indexOf(q) === -1) { return false; }
      return true;
    });
  }

  chip(f, active, kind) {
    var self = this;
    var on = f.key === active;
    return {
      label: f.label, count: f.count,
      bg: on ? f.soft : '#FFFFFF',
      fg: on ? f.color : '#45494F',
      border: on ? f.color : '#E4E1D6',
      pick: function () {
        var patch = {};
        patch[kind] = f.key;
        self.setState(patch);
      }
    };
  }

  renderVals() {
    var self = this;
    var list = this.filtered();
    return {
      q: this.state.q,
      onQuery: function (e) { self.setState({ q: e.target.value }); },
      domainFilters: DOMAIN_FILTERS.map(function (f) { return self.chip(f, self.state.dom, 'dom'); }),
      levelFilters: LEVEL_FILTERS.map(function (f) { return self.chip(f, self.state.lvl, 'lvl'); }),
      ideas: list,
      shown: this.fa(list.length),
      empty: list.length === 0
    };
  }
}
